function shortDate(value: string) { const d = new Date(value); return Number.isNaN(d.getTime()) ? value : d.toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }); }
function basename(path: string) { return path.split(/[\\/]/).pop() || path; }
function statusName(file: GitFile) { return file.conflict ? '冲突' : file.index === '?' ? '新增' : (file.index + file.worktree).includes('D') ? '删除' : (file.index + file.worktree).includes('R') ? '重命名' : '修改'; }
function ErrorText(error: unknown) { return error instanceof Error ? error.message : String(error); }
function IconButton({ title, children, onClick, disabled, className = '' }: { title: string; children: React.ReactNode; onClick?: () => void; disabled?: boolean; className?: string }) { return <button type="button" title={title} aria-label={title} className={`icon-button ${className}`} onClick={onClick} disabled={disabled}>{children}</button>; }
function Empty({ title, detail, icon = <GitCommitHorizontal size={30} /> }: { title: string; detail?: string; icon?: React.ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><strong>{title}</strong>{detail && <p>{detail}</p>}</div>; }

type TreeNode = { name: string; path: string; children: TreeNode[]; status?: string; submodule?: boolean };
function FileTree({ files, selected, onSelect }: { files: { path: string; status?: string; submodule?: boolean }[]; selected?: string; onSelect: (path: string) => void }) {
  const [closed, setClosed] = useState<Record<string, boolean>>({});
  const tree = useMemo(() => { const roots: TreeNode[] = []; for (const file of files) { let nodes = roots; const parts = file.path.split('/'); parts.forEach((name, index) => { const path = parts.slice(0, index + 1).join('/'); let node = nodes.find(n => n.name === name); if (!node) { node = { name, path, children: [] }; nodes.push(node); } if (index === parts.length - 1) { node.status = file.status || ' '; node.submodule = file.submodule; } nodes = node.children; }); } const sort = (nodes: TreeNode[]) => { nodes.sort((a, b) => Number(!!b.children.length) - Number(!!a.children.length) || a.name.localeCompare(b.name)); nodes.forEach(n => sort(n.children)); }; sort(roots); return roots; }, [files]);
  const render = (nodes: TreeNode[], depth = 0): React.ReactNode => nodes.map(node => node.children.length ? <div key={node.path}><button className="tree-folder" title={node.path} style={{ paddingLeft: 8 + depth * 13 }} onClick={() => setClosed(c => ({ ...c, [node.path]: !c[node.path] }))}>{closed[node.path] ? <ChevronRight size={11} /> : <ChevronDown size={11} />}<FolderOpen size={12} /><span>{node.name}</span></button>{!closed[node.path] && render(node.children, depth + 1)}</div> : <button className={`tree-file ${node.path === selected ? 'active' : ''}`} title={node.submodule ? `${node.path}（子模块）` : node.path} key={node.path} style={{ paddingLeft: 22 + depth * 13, paddingRight: 9 }} disabled={node.submodule} onClick={() => onSelect(node.path)}><FileCode2 size={12} /><span>{node.name}</span><i className={node.status?.startsWith('A') ? 'added' : ''}>{node.submodule ? '↗' : node.status?.trim().slice(0, 1)}</i></button>);
  return <div className="file-tree">{render(tree)}</div>;
}

function CodeViewer({ text }: { text: string | null }) {
  if (text === null) return <Empty title="选择文件以浏览代码" detail="查看当前选中提交的完整文件内容。" icon={<Code2 size={28} />} />;
  const token = /(\/\/.*$|#.*$|\/\*.*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:import|export|from|return|const|let|var|function|class|interface|type|public|private|protected|static|void|new|if|else|for|while|async|await|try|catch|throw|throws|package|extends|implements|default|switch|case|break|continue|true|false|null|undefined|def|self|using|namespace|fn|pub|use|struct|enum)\b|\b\d+(?:\.\d+)?\b)/g;
  const highlight = (line: string) => { const parts: React.ReactNode[] = []; let end = 0; for (const match of line.matchAll(token)) { const index = match.index!; if (index > end) parts.push(line.slice(end, index)); const value = match[0]; const kind = /^(\/\/|#|\/\*)/.test(value) ? 'comment' : /^['"`]/.test(value) ? 'string' : /^\d/.test(value) ? 'number' : 'keyword'; parts.push(<span className={`syntax-${kind}`} key={index}>{value}</span>); end = index + value.length; } if (end < line.length) parts.push(line.slice(end)); return parts; };
  return <div className="source-scroll"><div className="source-code">{text.split('\n').map((line, i) => <div className="source-line" key={i}><span className="line-number">{i + 1}</span><code>{highlight(line.replace(/\r$/, '')) || ' '}</code></div>)}</div></div>;
}

function ResizeHandle({ direction, onResize }: { direction: 'vertical' | 'horizontal'; onResize: (delta: number) => void }) {
  const [dragging, setDragging] = useState(false);
  return <div className={`resize-handle ${direction} ${dragging ? 'dragging' : ''}`} role="separator" aria-orientation={direction} onPointerDown={e => { e.preventDefault(); e.currentTarget.setPointerCapture(e.pointerId); setDragging(true); }} onPointerMove={e => { if (dragging) onResize(direction === 'vertical' ? e.movementX : e.movementY); }} onPointerUp={e => { setDragging(false); e.currentTarget.releasePointerCapture(e.pointerId); }} onLostPointerCapture={() => setDragging(false)} />;
}

function buildGraph(commits: GitCommit[]) {
  const lanes: string[] = []; const colors = ['#82d8ad', '#b6a4ef', '#8fc1ed', '#e8bd7f', '#e895a7'];
  return commits.map(commit => {
    let lane = lanes.indexOf(commit.hash);
    if (lane === -1) { lane = lanes.length; lanes.push(commit.hash); }
    const before = [...lanes]; const next = [...lanes]; next.splice(lane, 1);
    commit.parents.forEach((parent, index) => { if (!next.includes(parent)) next.splice(Math.min(lane + index, next.length), 0, parent); });
    const paths: { from: number; to: number; color: string; parent: boolean }[] = [];
    before.forEach((hash, index) => { if (hash !== commit.hash && next.includes(hash)) paths.push({ from: index, to: next.indexOf(hash), color: colors[index % colors.length], parent: false }); });
    commit.parents.forEach(parent => paths.push({ from: lane, to: next.indexOf(parent), color: colors[lane % colors.length], parent: true }));
    lanes.splice(0, lanes.length, ...next);
    return { lane, color: colors[lane % colors.length], paths, width: Math.max(before.length, next.length) };
  });
}

function DiffViewer({ diff, split }: { diff: DiffResult | null; split: boolean }) {
  if (!diff) return <Empty title="选择文件以查看差异" detail="工作区改动与历史提交，都在这里一目了然。" icon={<FileDiff size={30} />} />;
  if (diff.binary) return <Empty title="二进制文件" detail="该文件无法以文本差异显示。" icon={<Files size={30} />} />;
  if (!diff.text.trim()) return <Empty title="没有文本差异" detail="文件内容相同，或当前引用中没有可显示的变化。" icon={<CheckCheck size={30} />} />;
  let oldLine = 0; let newLine = 0;
  const rows = diff.text.split('\n').map((text, index) => {
    const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(text);
    if (hunk) { oldLine = Number(hunk[1]); newLine = Number(hunk[2]); return { text, kind: 'hunk', old: '', next: '', index }; }
    if (/^(diff |index |--- |\+\+\+ |new file|deleted file|similarity |rename |Binary )/.test(text)) return { text, kind: 'meta', old: '', next: '', index };
    if (text.startsWith('+')) return { text, kind: 'add', old: '', next: String(newLine++), index };
    if (text.startsWith('-')) return { text, kind: 'remove', old: String(oldLine++), next: '', index };
    if (text.startsWith(' ')) return { text, kind: 'context', old: String(oldLine++), next: String(newLine++), index };
    return { text, kind: 'meta', old: '', next: '', index };
  });
  return <div className={`diff-scroll ${split ? 'split' : ''}`}>
    {split && <div className="diff-column-head"><span>原始版本</span><span>修改后</span></div>}
    <div className="diff-code">{rows.map(row => split && !['meta', 'hunk'].includes(row.kind) ? <div className={`diff-pair ${row.kind}`} key={row.index}><div className={`diff-half ${row.kind === 'remove' ? 'remove' : ''}`}><span className="line-number">{row.old}</span><code>{row.kind === 'add' ? '' : row.text.slice(1)}</code></div><div className={`diff-half ${row.kind === 'add' ? 'add' : ''}`}><span className="line-number">{row.next}</span><code>{row.kind === 'remove' ? '' : row.text.slice(1)}</code></div></div> : <div className={`diff-line ${row.kind}`} key={row.index}><span className="line-number">{row.old}</span><span className="line-number">{row.next}</span><code>{row.text}</code></div>)}</div>
    {diff.truncated && <div className="inline-warning">差异内容较大，已截断显示。请使用外部编辑器检查完整文件。</div>}
  </div>;
}

